import "core-js/modules/es.array.push.js";
import { useDisplay } from "vuetify/lib/framework.mjs";
import SnackBar from "@/components/SnackBar.vue";
import DeleteActivity from "@/components/TimeSheets/PopUps/DeleteActivity.vue";
import { create_activity } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_activities } from "@/graphql/queries.js";
export default {
  components: {
    SnackBar,
    DeleteActivity
  },
  data() {
    return {
      height: 0,
      activityName: "",
      loading: false,
      headers: [{
        title: "Name",
        value: "activity_name",
        sortable: true,
        align: "start"
      }, {
        title: "Action",
        value: "actions",
        sortable: false,
        align: "center"
      }],
      tableData: [],
      SnackBarComponent: {},
      CommonVuetifyObj: {},
      tableHeight: 0,
      fixed: true,
      loadingBtn: false,
      projectDeletion: false,
      componentCheck: 0,
      deleteitems: {},
      totalItems: 0,
      currentPage: 1,
      itemsPerPage: 10,
      pageCount: 1,
      sortBy: [{
        key: "activity_name",
        order: "asc"
      }]
    };
  },
  computed: {
    sortedAndPaginatedItems() {
      const sortedItems = this.tableData.slice().sort((a, b) => {
        for (const sort of this.sortBy) {
          const aValue = this.getSortValue(a[sort.key], sort.key);
          const bValue = this.getSortValue(b[sort.key], sort.key);
          if (aValue < bValue) return sort.order === "asc" ? -1 : 1;
          if (aValue > bValue) return sort.order === "asc" ? 1 : -1;
        }
        return 0;
      });
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  mounted() {
    this.CommonVuetifyObj = useDisplay();
  },
  watch: {
    currentPage(newVal) {
      const table = document.querySelector(".dtwidth");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  created() {
    this.tableHeight = window.innerHeight - 290;
    this.fetch_activities();
  },
  methods: {
    getSortValue(value, key) {
      if (!value) return "";
      if (key === "activity_name") {
        return value.toLowerCase();
      }
      return value;
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
      this.currentPage = 1;
    },
    async add_mutation() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.create_activity_func();
      }
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.projectDeletion = false;
      this.fetch_activities();
    },
    delete_item(item) {
      this.deleteitems = item;
      this.componentCheck = 1;
      this.projectDeletion = true;
    },
    async create_activity_func() {
      var data = this.$store.getters.GetUserObj;
      this.loadingBtn = true;
      try {
        let result = await API.graphql(graphqlOperation(create_activity, {
          input: {
            activity_name: this.activityName,
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id
          }
        }));
        var response = JSON.parse(result.data.create_activity);
        if (response.Status == "SUCCESS") {
          this.loadingBtn = false;
          await this.fetch_activities();
          this.$emit("successMsg", response.Message);
          this.$refs.form.reset();
        } else {
          this.loadingBtn = false;
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loadingBtn = false;
        this.$refs.form.reset();
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    async fetch_activities() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(get_activities, {
          input: {
            organization_id: data.organization.organization_id
          }
        }));
        var response = JSON.parse(result.data.get_activities);
        this.tableData = [];
        if (response.Status == "SUCCESS") {
          this.loading = false;
          this.tableData = response.data;
          this.totalItems = this.tableData.length;
        } else {
          this.loading = false;
          this.tableData = [];
          this.totalItems = 0;
        }
      } catch (error) {
        this.loading = false;
        this.tableData = [];
        this.totalItems = 0;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
